// commands/send-thank-you-email.command.ts
@WorkflowCommand('sendThankYouEmail')
export class SendThankYouEmailCommand implements WorkflowCommandInterface {
  async execute(_subject: unknown, ctx: WorkflowExecutionContext): Promise<CommandResult> {
    try {
      await this.mailer.send(ctx.context.email as string, 'Thanks for your order!');
      return { ok: true, code: 'EMAILED' };
    } catch (err) {
      return { ok: true, code: 'EMAIL_FAILED' };  // non-critical, don't block the workflow
    }
  }
}

// observers/order-audit.observer.ts
export class OrderAuditObserver implements WorkflowObserver {
  readonly name = 'order-audit';
  async onEnter(event: StateEnterEvent): Promise<void> {
    await this.invoiceService.generateAndSend(event.instanceUuid);
    console.warn('audit:', event.toState);
  }
}
